import test from 'node:test';
import assert from 'node:assert/strict';
import { exportCsv } from '../src/export.js';

test('exportCsv empty array', () => {
  const result = exportCsv([]);
  assert.equal(result, 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due\n');
});

test('exportCsv single invoice', () => {
  const invoices = [
    {
      customerId: 'C-001',
      number: 'INV-2026-0001',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'issued',
      lines: [
        { sku: 'DES-HOUR', qty: 10, unitPrice: 8500, name: 'Design work (hour)', vatRate: 21, discountPercent: 0 },
      ],
    },
  ];
  const result = exportCsv(invoices);
  const lines = result.split('\n');
  assert.equal(lines.length, 3);
  assert.equal(lines[0], 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
  assert(lines[1].includes('INV-2026-0001'));
  assert(lines[1].includes('Alice'));
  assert(lines[1].includes('2026-10-01'));
  assert(lines[1].includes('2026-10-31'));
  assert(lines[1].includes('issued'));
  assert.equal(lines[2], '');
});

test('exportCsv multiple invoices', () => {
  const invoices = [
    {
      customerId: 'C-001',
      number: 'INV-2026-0001',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'issued',
      lines: [
        { sku: 'DES-HOUR', qty: 10, unitPrice: 8500, name: 'Design work (hour)', vatRate: 21, discountPercent: 0 },
      ],
    },
    {
      customerId: 'C-002',
      number: 'INV-2026-0002',
      issueDate: '2026-10-05',
      dueDate: '2026-11-04',
      status: 'issued',
      lines: [
        { sku: 'DEV-HOUR', qty: 5, unitPrice: 9500, name: 'Development (hour)', vatRate: 21, discountPercent: 0 },
      ],
    },
  ];
  const result = exportCsv(invoices);
  const lines = result.split('\n');
  assert.equal(lines.length, 4);
  assert(lines[1].includes('INV-2026-0001'));
  assert(lines[2].includes('INV-2026-0002'));
});

test('exportCsv amount formatting', () => {
  const invoices = [
    {
      customerId: 'C-001',
      number: 'INV-2026-0001',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'issued',
      lines: [
        { sku: 'DES-HOUR', qty: 10, unitPrice: 8500, name: 'Design work (hour)', vatRate: 21, discountPercent: 0 },
      ],
    },
  ];
  const result = exportCsv(invoices);
  assert(result.includes('85000.00'));
  assert(result.includes('17850.00'));
  assert(result.includes('102850.00'));
});

test('exportCsv no thousands separator', () => {
  const invoices = [
    {
      customerId: 'C-001',
      number: 'INV-2026-0001',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'issued',
      lines: [
        { sku: 'ITEM', qty: 1000, unitPrice: 100000, name: 'Item', vatRate: 21, discountPercent: 0 },
      ],
    },
  ];
  const result = exportCsv(invoices);
  assert(result.includes('100000000.00'));
  assert(!result.includes('100,000,000'));
  assert(!result.includes('100000000,00'));
});

test('exportCsv escapes commas', () => {
  const invoices = [
    {
      customerId: 'C-003',
      number: 'INV-2026-0001',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'issued',
      lines: [
        { sku: 'DES-HOUR', qty: 10, unitPrice: 8500, name: 'Design work (hour)', vatRate: 21, discountPercent: 0 },
      ],
    },
  ];
  const result = exportCsv(invoices);
  assert(result.includes('"Charlie, Inc."'));
});

